```php
<?php

function smart_sort_array($set, $order = 'desc') {
    // Check if the set is not empty
    if (empty($set)) {
        return [];
    }

    // Define the comparison logic based on the order parameter
    switch ($order) {
        case 'asc':
            usort($set, function($a, $b) {
                return $a['age'] <=> $b['age'];
            });
            break;
        case 'desc':
            usort($set, function($a, $b) {
                return $b['age'] <=> $a['age'];
            });
            break;
        default:
            throw new InvalidArgumentException("Order must be either 'asc' or 'desc'.");
    }

    return $set;
}

// Example usage
$people = [
    ['name' => 'Alice', 'address' => '', 'age' => 25],
    ['name' => 'Bob', 'address' => '', 'age' => 30],
    ['name' => 'Charlie', 'address' => '', 'age' => 28]
];

try {
    $sorted_people_asc = smart_sort_array($people);
    echo "Sorted in ascending order:\n";
    print_r($sorted_people_asc);

    $sorted_people_desc = smart_sort_array($people, 'desc');
    echo "Sorted in descending order:\n";
    print_r($sorted_people_desc);
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

